// Des: Tell the owner they're needed, in one plain line
// Flo: for each channel in noti_chai_orde > file = append to alerts.txt > toas = OS popup (PowerShell, notify-send, osascript) > true if any channel worked
// I/O: message line (caller, no private text) > alerts.txt in the state folder and/or an OS popup
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const cfgz = @import("cf-conf-load.zig");
const CF = .{ .file = "alerts.txt", .maxz = 1 << 20, .keep = 200 };
fn clean(aren: std.mem.Allocator, msg: []const u8) ![]u8 { const out = try aren.alloc(u8, msg.len); for (msg, 0..) |chr, ix| out[ix] = if (chr == '\'' or chr == '"' or chr == '\n' or chr == '\r' or chr == '`' or chr == '$') ' ' else chr; return out; }
pub fn appendFile(gpaz: std.mem.Allocator, iozz: std.Io, statd: []const u8, now: i64, msg: []const u8) !void { try std.Io.Dir.cwd().createDirPath(iozz, statd); const path = try std.fs.path.join(gpaz, &.{ statd, CF.file }); defer gpaz.free(path); const old = std.Io.Dir.cwd().readFileAlloc(iozz, path, gpaz, .limited(CF.maxz)) catch try gpaz.dupe(u8, ""); defer gpaz.free(old); const line = try std.fmt.allocPrint(gpaz, "{d} {s}\n", .{ now, msg }); defer gpaz.free(line); const all = try gpaz.alloc(u8, old.len + line.len); defer gpaz.free(all); @memcpy(all[0..old.len], old); @memcpy(all[old.len..], line); try std.Io.Dir.cwd().writeFile(iozz, .{ .sub_path = path, .data = all }); }
fn toast(gpaz: std.mem.Allocator, iozz: std.Io, aren: std.mem.Allocator, msg: []const u8) bool { const txt = clean(aren, msg) catch return false; const scr = std.fmt.allocPrint(aren, "Add-Type -AssemblyName System.Windows.Forms; $n=New-Object System.Windows.Forms.NotifyIcon; $n.Icon=[System.Drawing.SystemIcons]::Information; $n.Visible=$true; $n.ShowBalloonTip(10000,'fb','{s}','Info'); Start-Sleep 11; $n.Dispose()", .{txt}) catch return false; const mac = std.fmt.allocPrint(aren, "display notification \"{s}\" with title \"fb\"", .{txt}) catch return false; _ = gpaz; const argv: []const []const u8 = switch (builtin.os.tag) { .windows => &.{ "powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", scr }, .macos => &.{ "osascript", "-e", mac }, else => &.{ "notify-send", "fb", txt } }; _ = std.process.spawn(iozz, .{ .argv = argv, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }) catch return false; return true; }
pub fn send(gpaz: std.mem.Allocator, iozz: std.Io, aren: std.mem.Allocator, conf: cfgz.Conf, statd: []const u8, now: i64, msg: []const u8) bool { var okay = false; for (conf.noti_chai_orde) |tool| { if (std.mem.eql(u8, tool, "file")) { if (appendFile(gpaz, iozz, statd, now, msg)) |_| { okay = true; } else |_| {} } else if (std.mem.eql(u8, tool, "toas")) { if (toast(gpaz, iozz, aren, msg)) okay = true; } } return okay; }
